begin;
do $review$
declare item jsonb;field text;p public.hb_policy_versions%rowtype;s public.hb_policy_sources%rowtype;new_rules jsonb;
 synced timestamptz := '2026-10-12T06:14:00Z';
begin
 for item in select value from jsonb_array_elements($plans$[{"slug":"بدل-فاقد-أو-تالف-للهوية","source":"https://icp.gov.ae/en/services-details/?serviceid=64afe3c1035448005bd52e5b","authority":"icp","fields":["fees","duration"],"fees":"300 درهم لبدل فاقد أو تالف و100 درهم للخدمات الذكية. تسرد البطاقة 150 درهماً للخدمة العاجلة بالمراكز و150 درهماً للاستبدال مع تحديث البيانات بالمراكز. تحقّق من الرسوم المنطبقة على الخيار قبل الدفع.","feesEn":"AED 300 replacement and AED 100 smart services. The card separately lists AED 150 urgent-center service and AED 150 replacement with data update at centers. Confirm the applicable option before payment.","duration":"5 أيام وفق بطاقة الهيئة؛ لم تحدد البطاقة أنها أيام عمل.","durationEn":"5 days according to the ICP card; working days are not specified.","nameAr":"بدل فاقد أو تالف للهوية","nameEn":"Replace a Lost or Damaged Emirates ID","sourceReviewedAt":"2026-10-09","evidenceScope":"Official ICP card text retrieved through web source access; separate read-only browser returned HTTP 500.","priorVersion":1},{"slug":"الإعفاء-من-غرامة-تأخير-الهوية","source":"https://icp.gov.ae/en/services-details/?serviceid=64afe3c1035448005bd52e5f","authority":"icp","fields":["duration"],"duration":"يومان (2) وفق بطاقة الهيئة؛ لم تحدد البطاقة أنهما يوما عمل.","durationEn":"2 days according to the ICP card; it does not specify working days.","nameAr":"الإعفاء من غرامة تأخير الهوية","nameEn":"Apply for Exemption from Emirates ID Late Fees","sourceReviewedAt":"2026-10-09","evidenceScope":"Official ICP card text retrieved through web source access; separate read-only browser returned HTTP 500.","priorVersion":1},{"slug":"استرداد-رسوم-إصدار-الهوية-غير-المكتمل","source":"https://icp.gov.ae/en/services-details/?serviceid=64afe3c1035448005bd52e5e","authority":"icp","fields":["duration"],"duration":"5 أيام وفق بطاقة الهيئة؛ لم تحدد البطاقة أنها أيام عمل.","durationEn":"5 days according to the ICP card; working days are not specified.","nameAr":"استرداد رسوم إصدار الهوية غير المكتمل","nameEn":"Refund Fees for Incomplete Emirates ID Issuance","sourceReviewedAt":"2026-10-09","evidenceScope":"Official ICP card text retrieved through web source access; separate read-only browser returned HTTP 500.","priorVersion":1},{"slug":"issue-emirates-id-uae","source":"https://icp.gov.ae/en/services-details/?serviceid=64afe3c1035448005bd52e5a","authority":"icp","fields":["fees","duration"],"fees":"للمقيمين: 100 درهم عن كل سنة إقامة و100 درهم للخدمات الذكية. لمواطني الخليج: 100 درهم لبطاقة 5 سنوات و100 درهم للخدمات الذكية. للمواطنين: 100 درهم لمدة 5 سنوات أو 200 درهم لمدة 10 سنوات بحسب فئة العمر في البطاقة. تسرد الهيئة 150 درهماً للخدمة العاجلة بالمراكز عند انطباقها؛ تحقق من الإجمالي والخيار قبل الدفع.","feesEn":"Residents: AED 100 per residence year and AED 100 smart services. GCC citizens: AED 100 for 5 years and AED 100 smart services. UAE nationals: AED 100 for 5 years or AED 200 for 10 years according to the card's age category. ICP lists AED 150 urgent-center service where applicable; confirm the total and option before payment.","duration":"5 أيام وفق بطاقة الهيئة؛ لم تحدد البطاقة أنها أيام عمل.","durationEn":"5 days according to the ICP card; working days are not specified.","nameAr":"إصدار الهوية الإماراتية لأول مرة","nameEn":"New Identity Card Issuance","sourceReviewedAt":"2026-10-09","evidenceScope":"Official Arabic and English ICP card text retrieved through web source access.","priorVersion":1},{"slug":"renew-emirates-id-uae","source":"https://icp.gov.ae/en/services-details/?serviceid=64afe3c1035448005bd52e5d","authority":"icp","fields":["fees","duration"],"fees":"للمقيمين: 100 درهم عن كل سنة إقامة و100 درهم للخدمات الذكية. لمواطني الخليج: 100 درهم لبطاقة 5 سنوات و100 درهم للخدمات الذكية. للمواطنين: 100 درهم لمدة 5 سنوات أو 200 درهم لمدة 10 سنوات بحسب فئة العمر في البطاقة. تسرد الهيئة 150 درهماً للخدمة العاجلة بالمراكز عند انطباقها؛ تحقق من الإجمالي والخيار قبل الدفع.","feesEn":"Residents: AED 100 per residence year and AED 100 smart services. GCC citizens: AED 100 for 5 years and AED 100 smart services. UAE nationals: AED 100 for 5 years or AED 200 for 10 years according to the card's age category. ICP lists AED 150 urgent-center service where applicable; confirm the total and option before payment.","duration":"5 أيام وفق بطاقة الهيئة؛ لم تحدد البطاقة أنها أيام عمل.","durationEn":"5 days according to the ICP card; working days are not specified.","nameAr":"تجديد الهوية الإماراتية","nameEn":"Identity Card Renewal","sourceReviewedAt":"2026-10-09","evidenceScope":"Official Arabic and English ICP card text retrieved through web source access.","priorVersion":1},{"slug":"تمديد-التأشيرة-أو-إذن-الدخول","source":"https://icp.gov.ae/en/services-details/?serviceid=64afe3c1035448005bd52e62","authority":"icp","fields":["fees","duration"],"fees":"تسرد الهيئة 100 درهم للطلب و500 للتمديد المعتاد. توجد رسوم مختلفة للفئات الخاصة وتمديد الصلاحية قبل الوصول؛ راجع فئتك والإجمالي الرسمي قبل الدفع.","feesEn":"ICP lists AED 100 application and AED 500 standard extension. Special categories and pre-arrival validity have different fees; check your official category and total.","duration":"يومان (2) وفق بطاقة الهيئة؛ لم تحدد البطاقة أنها أيام عمل.","durationEn":"2 days according to the ICP card; working days are not specified.","nameAr":"تمديد التأشيرة أو إذن الدخول","nameEn":"Visa Extension","sourceReviewedAt":"2026-10-09","evidenceScope":"Requirements, fees, duration, access control and selected conditions of two ICP amendment cards. Categories remain conditional; no exact fine or expiry policy is inferred.","priorVersion":1},{"slug":"amendment-of-visa-data","source":"https://icp.gov.ae/en/services-details/?serviceid=64afe3c1035448005bd52e61","authority":"icp","fields":["fees","duration"],"fees":"50 درهماً للطلب و100 درهم للخدمة الذكية","feesEn":"AED 50 for the application and AED 100 for the smart service","duration":"يومان","durationEn":"Two days.","nameAr":"تعديل بيانات التأشيرة","nameEn":"Amendment of Visa Data","sourceReviewedAt":"2026-10-08","evidenceScope":"Requirements, fees, duration, access control and selected conditions of two ICP amendment cards. Categories remain conditional; no exact fine or expiry policy is inferred.","priorVersion":1},{"slug":"amendment-of-residency-permit-data","source":"https://icp.gov.ae/en/services-details/?serviceid=64afe3c1035448005bd52e67","authority":"icp","fields":["fees","duration"],"fees":"تعرض البطاقة 150 درهمًا لاستبدال الهوية لتحديث المعلومات المعروضة، و100 درهم للخدمات الذكية؛ راجع الفئة المختارة.","feesEn":"The card lists AED 150 for replacing the Emirates ID to update displayed information and AED 100 for smart services. Check the selected category.","duration":"يومان","durationEn":"Two days.","nameAr":"تعديل بيانات تصريح الإقامة","nameEn":"Amendment of Residency Permit Data","sourceReviewedAt":"2026-10-08","evidenceScope":"Requirements, fees, duration, access control and selected conditions of two ICP amendment cards. Categories remain conditional; no exact fine or expiry policy is inferred.","priorVersion":1}]$plans$::jsonb) loop
  begin
   select * into strict p from public.hb_policy_versions where policy_key='service:'||(item->>'slug') and status='active' for update;
   select * into strict s from public.hb_policy_sources where id=any(p.source_ids) and source_url=item->>'source' and authority_key='icp' and active for update;
  exception when no_data_found then raise notice 'Reviewed ICP policy absent in clean seed: %',item->>'slug';continue;end;
  select coalesce(jsonb_agg(value order by ordinality),'[]'::jsonb) into new_rules
  from jsonb_array_elements(p.rules) with ordinality
  where not (coalesce(value->>'id','') in (select jsonb_array_elements_text(item->'fields')));
  for field in select jsonb_array_elements_text(item->'fields') loop
   if field not in ('fees','duration') or coalesce(item->>field,'')='' or item->>field ~ 'غير موثق|غير مسجل' then raise exception 'Unreviewed ICP field: % %',item->>'slug',field;end if;
   new_rules:=new_rules||jsonb_build_array(jsonb_build_object('id',field,'when','[]'::jsonb,'effect','review','reason',item->>field,'actions',jsonb_build_array('review_'||field),'sourceRefs',jsonb_build_array(item->>'source')));
  end loop;
  if p.reviewed_by='reviewed-icp-field-sync-2026-10-12' and p.rules=new_rules then continue;end if;
  update public.hb_policy_versions set status='retired',effective_until=synced where id=p.id;
  insert into public.hb_policy_versions(policy_key,jurisdiction_id,version,effective_from,status,rules,source_ids,reviewed_by,reviewed_at,country_pack_id)
  values(p.policy_key,p.jurisdiction_id,p.version+1,synced,'active',new_rules,p.source_ids,'reviewed-icp-field-sync-2026-10-12',synced,p.country_pack_id);
  update public.hb_policy_sources set metadata=metadata||jsonb_build_object('reviewed_fields_grounding_checkpoint','reviewed-icp-field-sync-2026-10-12','reviewed_fields_grounding_synced_at',synced,'reused_source_reviewed_at',item->>'sourceReviewedAt','reviewed_fields_grounding_scope','Only explicitly reviewed fees/duration from accepted October 8/9 cards. No new source review or health reclassification. Unrecorded exemption/refund fees remain absent.') where id=s.id;
 end loop;
end $review$;
commit;
